begin;

-- subagents: generated by `npm run guide:content` from content/guide/subagents.ts. Edit the source, not this file.
update public.guide_steps set lesson = $json${
  "minutes": 16,
  "outcome": "Вы поручаете исследование, ревью и тесты субагентам — помощникам со своим контекстом, — и основная сессия остаётся чистой для решений.",
  "blocks": [
    {
      "type": "scene",
      "text": "Вы попросили агента разобраться, как устроены платежи. Через двадцать минут он прочитал сорок шесть файлов и выдал отличный обзор. А потом, на самой задаче, начал путаться: окно наполовину занято прочитанным, и задача в нём тонет."
    },
    {
      "type": "text",
      "text": "Субагент — отдельный агент, которого запускает основная сессия. Он работает в своём контекстном окне: читает десятки файлов, гоняет команды, а обратно возвращает только выводы. Ваше окно не засоряется (шаг 2.4), а работа идёт параллельно."
    },
    {
      "type": "bridge",
      "text": "Вы поручали коллеге разведку: «посмотри, как у соседей устроена авторизация, и расскажи главное». Он тратит день на чтение, а вам приносит страницу выводов. Субагент — такой коллега: читает он, а в ваше окно попадает только итог."
    },
    {
      "type": "why",
      "text": "У каждого субагента своё контекстное окно. Всё, что он прочитал и запустил, остаётся в нём, а основной сессии возвращается только итоговый ответ. Поэтому объём его работы почти не занимает ваше окно — но каждый его запрос к модели расходует лимиты отдельно."
    },
    {
      "type": "diagram",
      "name": "subagents",
      "caption": "Основная сессия держит план и решения. Субагенты читают и проверяют в своих окнах и приносят только итог."
    },
    {
      "type": "heading",
      "text": "Встроенные субагенты"
    },
    {
      "type": "list",
      "items": [
        "**Explore** — быстрый поиск и чтение кода, без права правки.",
        "**Plan** — исследование для режима планирования.",
        "**general-purpose** — универсальный помощник для многошаговых задач."
      ]
    },
    {
      "type": "text",
      "text": "Часто агент зовёт их сам. Но можно и прямо попросить: «Используй субагентов, чтобы найти все вызовы платёжного API и описать, где они различаются». По умолчанию субагенты работают в фоне: пока они читают, вы продолжаете разговор с основной сессией."
    },
    {
      "type": "heading",
      "text": "Свой субагент"
    },
    {
      "type": "code",
      "file": ".claude/agents/reviewer.md",
      "code": "---\nname: reviewer\ndescription: Свежим взглядом проверяет diff перед коммитом. Используй после крупных правок.\ntools: Read, Glob, Grep\nmodel: sonnet\n---\n\nТы ревьюер. Прочитай изменения и найди ошибки корректности,\nослабленные тесты и нарушения требований задачи.\nОтмечай только то, что ломает поведение. Стиль не трогай.",
      "caption": "`tools` ограничивает субагента чтением: ревьюеру незачем править файлы. По `description` основной агент решает, когда его позвать."
    },
    {
      "type": "session",
      "title": "~/projects/shop",
      "summary": "Симуляция сеанса: основная сессия поручает субагенту Explore найти все вызовы платёжного API, а субагенту reviewer — проверить готовый diff. Оба работают в своих окнах и возвращают короткие выводы.",
      "lines": [
        {
          "kind": "prompt",
          "text": "Субагентом найди все вызовы платёжного API, потом план миграции.",
          "typed": true
        },
        {
          "kind": "info",
          "text": "Explore: прочитано 46 файлов в своём окне"
        },
        {
          "kind": "info",
          "text": "Итог Explore: 7 вызовов, два — без обработки ошибок"
        },
        {
          "kind": "edit",
          "text": "src/payments/client.ts",
          "diff": "+38 −21"
        },
        {
          "kind": "prompt",
          "text": "Теперь пусть reviewer проверит diff.",
          "typed": true
        },
        {
          "kind": "info",
          "text": "reviewer: проблем корректности нет, один тест стоит усилить"
        },
        {
          "kind": "done",
          "text": "Готово. В основном окне — только выводы, а не 46 файлов."
        }
      ]
    },
    {
      "type": "spot",
      "title": "Ответ субагента · четыре варианта",
      "prompt": "Вы поручили субагенту найти вызовы платёжного API. Какой ответ стоит у него попросить?",
      "items": [
        {
          "id": "files",
          "text": "Полный текст всех 46 прочитанных файлов."
        },
        {
          "id": "list",
          "text": "Список из 7 вызовов с путями и строками; у двух нет обработки ошибок."
        },
        {
          "id": "done",
          "text": "«Готово, всё проверил»."
        },
        {
          "id": "log",
          "text": "Подробный журнал всех команд, которые он запускал."
        }
      ],
      "answer": "list",
      "reveal": "Основной сессии нужен итог, с которым можно работать: что найдено, где и что с этим не так. Полные файлы и журнал команд забьют ваше окно — ради его чистоты субагента и запускали. А «готово» без списка ничего не даёт."
    },
    {
      "type": "callout",
      "tone": "trap",
      "title": "Субагент тоже тратит лимиты",
      "text": "Каждый субагент делает свои запросы к модели. Пять субагентов на простой вопрос — лишний расход. Зовите их, когда задача действительно большая или нужен свежий взгляд."
    },
    {
      "type": "callout",
      "tone": "tip",
      "title": "Свежий взгляд — главное преимущество",
      "text": "Ревьюер-субагент не видит, как вы с агентом спорили о решении, — только код. Поэтому он замечает то, к чему автор уже привык (шаг 4.1)."
    },
    {
      "type": "sources",
      "links": [
        {
          "title": "Субагенты: свои окна, встроенные и собственные",
          "url": "https://code.claude.com/docs/en/sub-agents"
        },
        {
          "title": "Лучшие практики: исследования в отдельном контексте",
          "url": "https://code.claude.com/docs/en/best-practices"
        }
      ]
    }
  ],
  "practice": {
    "task": "Создайте в своём проекте субагента-ревьюера в `.claude/agents/` с доступом только на чтение. Дайте основной сессии задачу, а после правок попросите ревьюера проверить diff. Отдельно поручите Explore исследовательский вопрос о проекте.",
    "done": [
      "файл субагента лежит в `.claude/agents/` и закоммичен;",
      "ревьюер проверил реальный diff и нашёл или подтвердил что-то по делу;",
      "исследование прошло в субагенте, а основное окно осталось чистым."
    ]
  },
  "verified": {
    "date": "2026-10-07",
    "claudeCode": "2.1.292"
  },
  "check": {
    "questions": [
      {
        "id": "why-subagent",
        "prompt": "Нужно найти все вызовы платёжного API в большом проекте, а окно основной сессии уже наполовину заполнено. Как поступить?",
        "options": [
          {
            "id": "subagent",
            "text": "Поручить поиск субагенту: он прочитает файлы в своём окне и вернёт только список."
          },
          {
            "id": "main",
            "text": "Искать в основной сессии: так прочитанные файлы останутся у агента под рукой."
          },
          {
            "id": "compact",
            "text": "Сделать `/compact`, а потом искать в основной сессии."
          }
        ]
      },
      {
        "id": "reviewer-tools",
        "prompt": "Какой набор `tools` лучше дать субагенту-ревьюеру?",
        "options": [
          {
            "id": "read-only",
            "text": "`Read, Glob, Grep` — только чтение."
          },
          {
            "id": "all",
            "text": "Все инструменты, включая правку и Bash."
          },
          {
            "id": "none",
            "text": "Никаких: пусть только думает."
          }
        ]
      },
      {
        "id": "when-not",
        "prompt": "Когда субагент скорее лишний?",
        "options": [
          {
            "id": "small",
            "text": "Чтобы найти одну функцию в известном файле."
          },
          {
            "id": "big-search",
            "text": "Чтобы прочитать полсотни файлов и найти закономерность."
          },
          {
            "id": "review",
            "text": "Чтобы свежим взглядом проверить большой diff."
          }
        ]
      }
    ]
  }
}$json$::jsonb where step_id = 'subagents';
insert into private.guide_checks (step_id, key) values ('subagents', $json${
  "why-subagent": {
    "correct": [
      "subagent"
    ],
    "why": {
      "subagent": "Да. Прочитанные им файлы остаются у него, а вы получаете итог.",
      "main": "Десятки прочитанных файлов займут окно, и к концу задачи ответы станут хуже (шаг 2.1).",
      "compact": "Сжатие освободит место, но поиск снова заполнит окно. Объём лучше отдать в отдельный контекст."
    }
  },
  "reviewer-tools": {
    "correct": [
      "read-only"
    ],
    "why": {
      "read-only": "Да. Ревьюеру нужно читать, а не править: так он не «починит» найденное втихую.",
      "all": "Лишние права для задачи, где нужно только смотреть.",
      "none": "Без чтения файлов ревьюер не увидит код."
    }
  },
  "when-not": {
    "correct": [
      "small"
    ],
    "why": {
      "small": "Да. Быстрее спросить напрямую: субагент потратит запросы на то, что делается за секунду.",
      "big-search": "Как раз хороший случай: объём уйдёт в окно субагента.",
      "review": "Тоже хороший случай: ревьюеру полезен чистый контекст."
    }
  }
}$json$::jsonb)
on conflict (step_id) do update set key = excluded.key;

-- worktrees: generated by `npm run guide:content` from content/guide/worktrees.ts. Edit the source, not this file.
update public.guide_steps set lesson = $json${
  "minutes": 15,
  "outcome": "Вы ведёте несколько задач параллельно в разных сессиях, и они не мешают друг другу — каждая в своей рабочей копии.",
  "blocks": [
    {
      "type": "scene",
      "text": "Вы запустили агента на корзину, а во втором терминале, в той же папке, — на отчёты. Первый переключил ветку, чтобы проверить старое поведение, — и второй продолжил писать отчёты поверх чужой ветки. Коммит с отчётами уехал не туда, и в него попала половина правок корзины."
    },
    {
      "type": "text",
      "text": "Две сессии Claude Code в одной папке — это два агента, которые правят одни и те же файлы. Чтобы вести задачи параллельно, каждой нужна своя рабочая копия. Git умеет это давно: worktree — отдельная папка с отдельной веткой из того же репозитория."
    },
    {
      "type": "bridge",
      "text": "Вы держали второй клон репозитория, чтобы чинить прод-баг, не бросая фичу: отдельная папка, своя ветка, свои зависимости. Worktree — то же самое без второго клона: одна история git и несколько рабочих папок."
    },
    {
      "type": "why",
      "text": "Сессия агента работает с файлами папки, в которой запущена, и с её текущей веткой. Две сессии в одной папке делят и файлы, и ветку: правка или `git switch` одной сразу меняет мир другой. Worktree даёт каждой сессии свою папку и свою ветку при общей истории git."
    },
    {
      "type": "command",
      "code": "claude --worktree promo",
      "caption": "Создаст `.claude/worktrees/promo/` на новой ветке `worktree-promo` и откроет в ней сессию. Короткая форма — `-w`."
    },
    {
      "type": "heading",
      "text": "Как это устроено"
    },
    {
      "type": "list",
      "items": [
        "**Отдельная папка и ветка**: правки одной сессии не видны другой, пока вы их не сольёте.",
        "**Уборка при выходе**: чистую копию, созданную без имени, Claude Code удалит сам, а если имя вы задали, сначала спросит. Копию с изменениями он предложит оставить.",
        "**Вручную** тоже можно: `git worktree add ../shop-promo -b promo`, а потом `claude` в этой папке."
      ]
    },
    {
      "type": "session",
      "title": "два терминала",
      "summary": "Симуляция: в первом терминале агент работает в рабочей копии promo над промокодами, во втором — в копии reports над отчётами. Каждый правит свои файлы на своей ветке и прогоняет свои тесты.",
      "lines": [
        {
          "kind": "command",
          "text": "claude -w promo",
          "typed": true
        },
        {
          "kind": "info",
          "text": "Рабочая копия .claude/worktrees/promo, ветка worktree-promo"
        },
        {
          "kind": "edit",
          "text": "src/cart/promo.ts",
          "diff": "+41"
        },
        {
          "kind": "command",
          "text": "claude -w reports   # во втором терминале",
          "typed": true
        },
        {
          "kind": "info",
          "text": "Рабочая копия .claude/worktrees/reports, ветка worktree-reports"
        },
        {
          "kind": "edit",
          "text": "src/reports/csv.ts",
          "diff": "+48"
        },
        {
          "kind": "pass",
          "text": "Тесты в обеих копиях проходят независимо"
        },
        {
          "kind": "done",
          "text": "Две задачи идут параллельно и не пересекаются."
        }
      ]
    },
    {
      "type": "callout",
      "tone": "trap",
      "title": "Каждая копия — с нуля",
      "text": "Worktree — свежая выгрузка: `node_modules` и локальных файлов вроде `.env` там нет. Установите зависимости в каждой копии, а нужные локальные файлы перечислите в `.worktreeinclude`: Claude Code скопирует те, что подходят под шаблон и при этом игнорируются git. И следите за портами: два дев-сервера на одном порту не уживутся."
    },
    {
      "type": "spot",
      "title": ".worktreeinclude · четыре кандидата",
      "prompt": "Все четыре пути игнорируются git. Какой не стоит добавлять в `.worktreeinclude`?",
      "items": [
        {
          "id": "env",
          "text": "`.env.local` с ключами для разработки."
        },
        {
          "id": "modules",
          "text": "`node_modules/`, чтобы не ставить зависимости заново."
        },
        {
          "id": "config",
          "text": "`config/local.json` с адресом локальной базы."
        },
        {
          "id": "settings",
          "text": "`.claude/settings.local.json` с вашими личными разрешениями."
        }
      ],
      "answer": "modules",
      "reveal": "Зависимости в новой копии ставят заново — сами или попросив агента: так они соответствуют lock-файлу этой ветки. `.worktreeinclude` — для небольших локальных файлов, которых нет в git: ключей и личных настроек."
    },
    {
      "type": "callout",
      "tone": "tip",
      "title": "Курс, который вы читаете, так и делался",
      "text": "Лендинг и кабинет этого сайта разрабатывались параллельно: лендинг — в отдельной рабочей копии на своей ветке, кабинет — в основной. Две сессии агента ни разу не правили один файл одновременно."
    },
    {
      "type": "sources",
      "links": [
        {
          "title": "Worktrees: параллельные сессии в отдельных копиях",
          "url": "https://code.claude.com/docs/en/worktrees"
        },
        {
          "title": "Типовые сценарии: параллельные сессии",
          "url": "https://code.claude.com/docs/en/common-workflows"
        }
      ]
    }
  ],
  "practice": {
    "task": "Возьмите две независимые задачи и запустите их в двух рабочих копиях: `claude -w <имя>` в двух терминалах. Доведите обе до коммита на своих ветках и слейте по очереди.",
    "done": [
      "обе задачи шли параллельно в своих рабочих копиях;",
      "в каждой копии установлены зависимости и проходят тесты;",
      "ветки слиты без конфликтов или конфликт разобран осознанно."
    ]
  },
  "verified": {
    "date": "2026-10-07",
    "claudeCode": "2.1.292"
  },
  "check": {
    "questions": [
      {
        "id": "two-sessions",
        "prompt": "Вы хотите, чтобы два агента одновременно делали две разные задачи. Как избежать того, что они перетрут правки друг друга?",
        "options": [
          {
            "id": "worktree",
            "text": "Запустить каждую сессию в своей рабочей копии: `claude -w <имя>`."
          },
          {
            "id": "same-folder",
            "text": "Открыть две сессии в одной папке и попросить быть аккуратными."
          },
          {
            "id": "sequential",
            "text": "Только по очереди: параллельная работа невозможна."
          }
        ]
      },
      {
        "id": "fresh-copy",
        "prompt": "В новой рабочей копии не запускаются тесты: нет зависимостей и `.env`. Почему?",
        "options": [
          {
            "id": "fresh",
            "text": "Worktree — свежая выгрузка: игнорируемых файлов нет, зависимости ставятся заново."
          },
          {
            "id": "broken",
            "text": "Worktree создался с ошибкой: его нужно удалить и создать заново."
          },
          {
            "id": "symlink",
            "text": "Так задумано: worktree берёт `node_modules` и `.env` по ссылке, а она сломалась."
          }
        ]
      },
      {
        "id": "cleanup",
        "prompt": "Что произойдёт с рабочей копией, если выйти из сессии с незакоммиченными изменениями?",
        "options": [
          {
            "id": "ask",
            "text": "Claude Code предложит её оставить, чтобы работа не пропала."
          },
          {
            "id": "delete",
            "text": "Удалится вместе с изменениями: рабочие копии временные."
          },
          {
            "id": "merge",
            "text": "Изменения автоматически сольются в ветку, с которой начинали."
          }
        ]
      }
    ]
  }
}$json$::jsonb where step_id = 'worktrees';
