-- agent-sdk: generated by `npm run guide:content` from content/guide/agent-sdk.ts. Edit the source, not this file.
update public.guide_steps set lesson = $json${
  "minutes": 17,
  "outcome": "Вы встраиваете агента в свои скрипты и сервисы — через `claude -p` или Agent SDK — с ограниченными правами и разбором результата.",
  "blocks": [
    {
      "type": "scene",
      "text": "Ночной скрипт разбирал ошибки через `claude -p` и заводил по ним задачи. Через месяц пришёл счёт: каждый запуск заново читал полрепозитория, а стоимость прогонов никто не записывал. Какой из сценариев окупается, сказать было нечем."
    },
    {
      "type": "text",
      "text": "Всё, что Claude Code делает в терминале, можно вызвать из кода: разбор входящих ошибок, черновик ответа на тикет, ночной поиск устаревших зависимостей. Есть два пути: командная строка для скриптов и SDK для сервисов."
    },
    {
      "type": "bridge",
      "text": "Вы встраивали в сервис сторонний API: ключ в секретах, явные лимиты, логирование ответов и стоимости. Агент в коде — такой же внешний сервис, только вместо одного ответа он выполняет цепочку действий."
    },
    {
      "type": "why",
      "text": "В терминале границы задаёте вы: смотрите на каждый шаг и отвечаете на вопросы о правах. В скрипте и сервисе спрашивать некого, поэтому всё, что агенту можно, задаётся в самом вызове: инструменты, режим, формат ответа. А раз каждый вызов стоит денег и проходит без вас, его результат и стоимость стоит сохранять."
    },
    {
      "type": "heading",
      "text": "Из скрипта: claude -p"
    },
    {
      "type": "command",
      "code": "claude -p \"Разбери этот лог и назови причину\" --output-format json --allowedTools \"Read,Grep\" < error.log",
      "caption": "Запрос без интерактива. JSON содержит `result`, `session_id` и `total_cost_usd` — удобно разбирать и считать расходы."
